"use client";

import { use } from "react";
import { getBlogBySlug } from "@/data/blogs";
import { ArrowLeft, Share2, Facebook, Twitter, Linkedin, MessageSquare } from "lucide-react";
import Link from "next/link";
import { motion } from "framer-motion";
import FinalCTA from "@/components/sections/FinalCTA";

export default function BlogDetail({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  const blog = getBlogBySlug(slug);

  if (!blog) return <div>Article not found</div>;

  return (
    <div className="pt-32 pb-24">
      {/* Article Header */}
      <section className="px-6 mb-20">
        <div className="max-w-4xl mx-auto">
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
          >
            <Link href="/blogs" className="inline-flex items-center gap-2 text-foreground/40 hover:text-primary transition-colors mb-12 group">
              <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
              Back to Blog
            </Link>
          </motion.div>

          <div className="space-y-6">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="px-4 py-1.5 bg-primary/10 border border-primary/20 rounded-full text-[10px] uppercase tracking-widest text-primary font-bold w-fit"
            >
              {blog.category}
            </motion.div>
            <motion.h1
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="text-4xl md:text-6xl font-black text-foreground leading-tight font-outfit"
            >
              {blog.title}
            </motion.h1>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.2 }}
              className="flex flex-wrap items-center gap-6 pt-6 border-t border-border"
            >
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-gradient-to-br from-primary to-accent rounded-full flex items-center justify-center font-bold text-white shadow-lg shadow-primary/20">
                  W
                </div>
                <div>
                  <p className="text-foreground font-bold text-sm">{blog.author}</p>
                  <p className="text-foreground/30 dark:text-white/30 text-[10px]">{blog.date} • {blog.readTime}</p>
                </div>
              </div>
              <div className="flex items-center gap-4 ml-auto">
                <button className="p-3 bg-primary/5 dark:bg-white/5 rounded-full hover:bg-primary/10 dark:hover:bg-white/10 text-foreground/40 dark:text-white/40 hover:text-primary dark:hover:text-white transition-all border border-border hover:border-primary/50 group">
                  <Twitter className="w-4 h-4 transition-transform group-hover:scale-110" />
                </button>
                <button className="p-3 bg-primary/5 dark:bg-white/5 rounded-full hover:bg-primary/10 dark:hover:bg-white/10 text-foreground/40 dark:text-white/40 hover:text-primary dark:hover:text-white transition-all border border-border hover:border-primary/50 group">
                  <Linkedin className="w-4 h-4 transition-transform group-hover:scale-110" />
                </button>
                <button className="p-3 bg-primary/5 dark:bg-white/5 rounded-full hover:bg-primary/10 dark:hover:bg-white/10 text-foreground/40 dark:text-white/40 hover:text-primary dark:hover:text-white transition-all border border-border hover:border-primary/50 group">
                  <Share2 className="w-4 h-4 transition-transform group-hover:scale-110" />
                </button>
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* Article Content */}
      <article className="px-6 mb-32">
        <div className="max-w-3xl mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="prose dark:prose-invert prose-lg max-w-none text-foreground/70 leading-relaxed space-y-8"
          >
            <p className="text-xl text-foreground/90 dark:text-white/90 font-medium leading-relaxed italic border-l-4 border-primary pl-8 py-2">
              {blog.excerpt}
            </p>

            <p>
              {blog.content}
            </p>

            <h3 className="text-2xl font-bold text-foreground dark:text-white font-outfit pt-8">The Core Principles</h3>
            <p>
              In our experience building dozens of high-performance applications, we've found that performance isn't something you can sprinkle on at the end. It's a fundamental architectural decision.
            </p>

            <div className="glass p-8 rounded-3xl border-border dark:border-primary/20 my-12 bg-background/50 shadow-premium">
              <h4 className="text-xl font-bold text-foreground dark:text-white mb-4 font-outfit">Key Takeaways</h4>
              <ul className="space-y-4 text-base">
                <li className="flex gap-4">
                  <div className="w-2 h-2 bg-primary rounded-full mt-2 shrink-0" />
                  <span>Always prioritize server-side rendering for critical data.</span>
                </li>
                <li className="flex gap-4">
                  <div className="w-2 h-2 bg-primary rounded-full mt-2 shrink-0" />
                  <span>Optimize images and assets using modern compression.</span>
                </li>
                <li className="flex gap-4">
                  <div className="w-2 h-2 bg-primary rounded-full mt-2 shrink-0" />
                  <span>Use GSAP for performance-safe animations that don't jank.</span>
                </li>
              </ul>
            </div>

            <p>
              We believe that the future of the web belongs to those who prioritize the user's experience across all devices and connection speeds.
            </p>
          </motion.div>

        </div>
      </article>

      <FinalCTA />
    </div>
  );
}
